        parent[A] = -1;
        dist[A] = 0;

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(A);

        int B = A;
        int D = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.add(v);
                    if (dist[v] > D) {
                        D = dist[v];
                        B = v;
                    }
                }
            }
        }

        int[] path = new int[D + 1];
        int idx = D;
        for (int v = B; v != -1; v = parent[v]) {
            path[idx--] = v;
        }

        long ways;

        if (D % 2 == 0) {
            int center = path[D / 2];
            int h = D / 2;
            ways = countEven(center, h);
        } else {
            int h = D / 2;
            int c1 = path[h];
            int c2 = path[h + 1];
            long cnt1 = countAtDepth(c1, c2, h);
            long cnt2 = countAtDepth(c2, c1, h);
            ways = cnt1 * cnt2;
        }

        System.out.println(D + 1);
        System.out.println(ways);
    }

    static int farthest(int start) {
        int[] dist = new int[N + 1];
        Arrays.fill(dist, -1);

        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[start] = 0;
        q.add(start);

        int far = start;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > dist[far]) {
                        far = v;
                    }
                }
            }
        }

        return far;
    }

    static long countEven(int center, int h) {
        int[] depth = new int[N + 1];
        int[] branch = new int[N + 1];
        int[] cnt = new int[N + 1];

        Arrays.fill(depth, -1);
        depth[center] = 0;

        ArrayDeque<Integer> q = new ArrayDeque<>();

        for (int nb : adj[center]) {
            depth[nb] = 1;
            branch[nb] = nb;
            q.add(nb);
        }

        while (!q.isEmpty()) {
            int u = q.poll();

            if (depth[u] == h) {
                cnt[branch[u]]++;
                continue;
            }

            for (int v : adj[u]) {
                if (depth[v] == -1) {
                    depth[v] = depth[u] + 1;
                    branch[v] = branch[u];
                    q.add(v);
                }
            }
        }

        long total = 0;
        long sumSq = 0;

        for (int nb : adj[center]) {
            int x = cnt[nb];
            if (x > 0) {
                total += x;
                sumSq += (long) x * x;
            }
        }

        return (total * total - sumSq) / 2;
    }

    static long countAtDepth(int start, int blocked, int target) {
        int[] depth = new int[N + 1];
        Arrays.fill(depth, -1);
        depth[start] = 0;

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(start);

        long count = 0;

        while (!q.isEmpty()) {
            int u = q.poll();

            if (depth[u] == target) {
                count++;
                continue;
            }

            for (int v : adj[u]) {
                if (v == blocked || depth[v] != -1) continue;
                depth[v] = depth[u] + 1;
                q.add(v);
            }
        }

        return count;
    }
